90		// Boundary: collected exactly at receive time is allowed.
91		exact := hb("n1", 1, receive, "1.0", 10, 0)
92		if err := ValidateHeartbeat(exact, receive); err != nil {
93			t.Errorf("collected_at == receive_time should be allowed: %v", err)
94		}
